"""Filesystem locations shared with the Next.js app (see lib/paths.ts)."""
from __future__ import annotations

import os
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
DATA_DIR = Path(os.environ.get("DROP_DATA_DIR", ROOT / "data"))
PROJECTS_DIR = Path(os.environ.get("DROP_PROJECTS_DIR", ROOT / "projects"))
DB_PATH = DATA_DIR / "drop.db"
SCHEMA_PATH = ROOT / "db" / "schema.sql"


def project_dir(project_id: str) -> Path:
    # Project ids are generated by us (nanoid alphabet); refuse anything else.
    if not project_id or any(c not in "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-" for c in project_id):
        raise ValueError(f"bad project id: {project_id!r}")
    return PROJECTS_DIR / project_id
